use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut r: int = -1
    let mut i: int = 0
    for x in ks {
        if x == k {
            r = i
        }
        i += 1
    }
    r
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let idx = find(ks.clone(), k)
            if idx >= 0 {
                ks.remove(idx)
                vs.remove(idx)
            }
            ks.push(k)
            vs.push(v)
            if ks.len() > cap {
                let ek = ks[0]
                ks.remove(0)
                vs.remove(0)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let idx = find(ks.clone(), k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vs[idx]
                ks.remove(idx)
                vs.remove(idx)
                ks.push(k)
                vs.push(v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                for x in ks {
                    out.insert(0, "${x}")
                }
                println(out.join(" "))
            }
        }
    }
}

